<?php
declare(strict_types=1);

require_once __DIR__ . '/includes/init.php';
require_once __DIR__ . '/csrf_helper.php';
require_once __DIR__ . '/includes/shop_manual_catalog.php';
require_once __DIR__ . '/includes/shop_product_image.php';
require_once __DIR__ . '/includes/shop_storefront.php';
require_once __DIR__ . '/includes/shop_attribute.php';
require_once __DIR__ . '/includes/shop_catalog_management.php';
require_once __DIR__ . '/includes/shop_catalog_publication.php';
if (!isset($_SESSION['trener_id']) || !roleAtLeast('admin')) {
    header('Location: login.php');
    exit;
}

function productAdminH(mixed $value): string { return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
function productAdminMoney(mixed $minor): string { return $minor===null?'':number_format((int)$minor/100,2,',',''); }
function productAdminNullableInt(string $value): ?int
{
    $value=trim($value);
    if($value==='')return null;
    if(preg_match('/^[0-9]+$/D',$value)!==1)throw new InvalidArgumentException('Číselná hodnota nemá platný formát.');
    return(int)$value;
}
function productAdminNullableBool(string $value): ?int
{
    if($value==='')return null;
    if(!in_array($value,['0','1'],true))throw new InvalidArgumentException('Příznak ano/ne není platný.');
    return(int)$value;
}
function productAdminGeneratedSku(): string
{
    return shopCatalogManualSkuPrefix() . strtoupper(bin2hex(random_bytes(5)));
}
function productAdminStatusLabel(string $status): string
{
    return ['active'=>'Aktivní','draft'=>'Koncept','inactive'=>'Neaktivní'][$status]??$status;
}
function productAdminOfferLabel(string $type): string
{
    return ['goods'=>'Zboží','program'=>'Kroužek','camp'=>'Tábor','club_event'=>'Klubová akce','rental'=>'Pronájem'][$type]??$type;
}
function productAdminOriginLabel(string $origin): string
{
    return $origin==='manual'?'Ručně založený':'Převedený z původního katalogu';
}
function productAdminVariantCountLabel(int $count): string
{
    return $count===1?'1 varianta':($count>=2&&$count<=4?$count.' varianty':$count.' variant');
}
/** @param array<string,array<string,mixed>> $definitions */
function productAdminAttributesJson(array $source,array $definitions):string
{
    return shopAttributeFormJson($source,$definitions);
}
/** @param array<string,array<string,mixed>> $definitions @return array<string,mixed> */
function productAdminVariantInput(array $source,array $definitions=[]): array
{
    return [
        'sku'=>(string)($source['sku']??''),'ean'=>(string)($source['ean']??''),
        'attributes_json'=>productAdminAttributesJson($source,$definitions),
        'amount_minor'=>(int)couponAdminMoneyInput((string)($source['amount']??'')),
        'compare_at_amount_minor'=>couponAdminMoneyInput((string)($source['compare_at_amount']??''),true),
        'includes_vat'=>productAdminNullableBool((string)($source['includes_vat']??'')),
        'vat_rate_basis_points'=>productAdminNullableInt((string)($source['vat_rate_basis_points']??'')),
        'stock_quantity_decimal'=>(string)($source['stock_quantity_decimal']??''),
        'unit_code'=>(string)($source['unit_code']??''),'visible'=>($source['visible']??'')==='1'?1:0,
    ];
}

/** @param array<string,array<string,mixed>> $definitions */
function productAdminAttributeEditor(array $definitions,string $json,string $prefix):string
{
    try{$decoded=json_decode($json,true,64,JSON_THROW_ON_ERROR);}catch(JsonException){$decoded=[];}if(!is_array($decoded))$decoded=[];
    $listId='attribute-keys-'.preg_replace('/[^A-Za-z0-9_-]/','',$prefix);ob_start();?>
    <div class="col-12" data-attribute-editor><label class="form-label">Volitelné parametry varianty</label><datalist id="<?=productAdminH($listId)?>"><?php foreach($definitions as$definition):if((int)$definition['active']!==1)continue;?><option value="<?=productAdminH($definition['attribute_key'])?>"><?=productAdminH($definition['display_name'])?></option><?php endforeach;?></datalist><div class="vstack gap-2" data-attribute-rows><?php if($decoded===[]):?><div class="small text-muted" data-no-attributes>Žádné parametry. Produkt lze založit i bez nich.</div><?php endif;?><?php foreach($decoded as$key=>$value):?><div class="row g-2 align-items-center" data-attribute-row><div class="col-md-5"><input class="form-control form-control-sm" name="attribute_keys[]" list="<?=productAdminH($listId)?>" value="<?=productAdminH($key)?>" placeholder="Název, např. Velikost"></div><div class="col-md-6" data-value-cell><input class="form-control form-control-sm" data-attribute-value name="attribute_values[]" value="<?=productAdminH(shopAttributeValueText($value))?>" placeholder="Hodnota"></div><div class="col-md-1 d-grid"><button class="btn btn-sm btn-outline-danger" type="button" data-remove-attribute aria-label="Odebrat parametr">×</button></div></div><?php endforeach;?></div><button class="btn btn-sm btn-outline-secondary mt-2" type="button" data-add-attribute>Přidat parametr</button><div class="form-text">Parametry nejsou povinné. Každý se zadává jednoduše jako název a hodnota.</div><template><div class="row g-2 align-items-center" data-attribute-row><div class="col-md-5"><input class="form-control form-control-sm" name="attribute_keys[]" list="<?=productAdminH($listId)?>" placeholder="Název parametru"></div><div class="col-md-6" data-value-cell><input class="form-control form-control-sm" data-attribute-value name="attribute_values[]" placeholder="Hodnota"></div><div class="col-md-1 d-grid"><button class="btn btn-sm btn-outline-danger" type="button" data-remove-attribute aria-label="Odebrat parametr">×</button></div></div></template></div>
    <?php return(string)ob_get_clean();
}

$errors=[];$actorId=(int)$_SESSION['trener_id'];$selectedId=max(0,(int)($_GET['id']??$_POST['product_id']??0));$attributeDefinitions=shopAttributeDefinitions($pdo,true);
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!csrf_verify((string)($_POST['csrf_token']??'')))$errors[]='Formulář vypršel. Obnovte stránku.';
    else{
        try{
            $action=(string)($_POST['action']??'');$reason=(string)($_POST['reason']??'');$confirmed=($_POST['confirm_action']??'')==='1';
            if($action==='create'){
                $_POST['sku']=trim((string)($_POST['sku']??''))!==''?(string)$_POST['sku']:productAdminGeneratedSku();
                $_POST['offer_type']='goods';$_POST['item_type']='product';$_POST['visibility']='visible';$_POST['visible']='1';
                $result=shopManualCatalogCreate($pdo,$actorId,$_POST,productAdminVariantInput($_POST,$attributeDefinitions),$reason,$confirmed);
                $_SESSION['product_admin_flash']='Produkt byl založen. Níže jej můžete rovnou zveřejnit.';
                header('Location: eshop_produkt_admin.php?id='.(int)$result['product_id'],true,303);exit;
            }
            if($action==='update_product'){
                shopManualCatalogUpdateProduct($pdo,$actorId,$selectedId,$_POST,$reason,$confirmed);
                $_SESSION['product_admin_flash']='Produkt byl auditovaně upraven.';
            }elseif($action==='update_variant'){
                shopManualCatalogUpdateVariant($pdo,$actorId,(int)($_POST['variant_id']??0),productAdminVariantInput($_POST,$attributeDefinitions),$reason,$confirmed);
                $_SESSION['product_admin_flash']='Varianta byla auditovaně upravena.';
            }elseif($action==='add_variant'){
                shopManualCatalogAddVariant($pdo,$actorId,$selectedId,productAdminVariantInput($_POST,$attributeDefinitions),$reason,$confirmed);
                $_SESSION['product_admin_flash']='Nová sezonní varianta byla přidána v konceptu.';
            }elseif($action==='adjust_stock'){
                shopCatalogAdjustStock($pdo,$actorId,(int)($_POST['variant_id']??0),(string)($_POST['stock_quantity_decimal']??''),$reason,$confirmed);
                $_SESSION['product_admin_flash']='Sklad byl auditovaně opraven samostatným pohybem.';
            }elseif($action==='add_image'){
                $upload=$_FILES['product_image']??null;
                if(!is_array($upload)||(int)($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new InvalidArgumentException('Vyberte JPG nebo PNG obrázek do 5 MB.');
                shopProductImageAdd($pdo,$actorId,$selectedId,(string)($upload['tmp_name']??''),(int)($_POST['sort_order']??0),$reason,$confirmed,true);
                $_SESSION['product_admin_flash']='Obrázek byl bezpečně překódován, zbaven metadat a přidán.';
            }elseif($action==='reorder_image'){
                shopProductImageUpdateOrder($pdo,$actorId,(int)($_POST['image_id']??0),(int)($_POST['sort_order']??0),$reason,$confirmed);
                $_SESSION['product_admin_flash']='Pořadí obrázku bylo auditovaně změněno.';
            }elseif($action==='remove_image'){
                shopProductImageRemove($pdo,$actorId,(int)($_POST['image_id']??0),$reason,$confirmed);
                $_SESSION['product_admin_flash']='Obrázek byl odebrán a lokální soubor přesunut do karantény.';
            }elseif($action==='archive'){
                shopManualCatalogArchive($pdo,$actorId,$selectedId,$reason,$confirmed);
                $_SESSION['product_admin_flash']='Produkt byl deaktivován a archivován.';
            }elseif($action==='publish'){
                $publicName=(string)($_POST['public_name']??'');$publicSummary=(string)($_POST['public_summary']??'');
                if(trim($publicSummary)==='')$publicSummary=$publicName;
                shopCatalogPublicationActivate($pdo,$selectedId,$actorId,$publicName,$publicSummary,$reason,$confirmed);
                $_SESSION['product_admin_flash']='Produkt je zveřejněný v e-shopu.';
            }elseif($action==='unpublish'){
                if(!$confirmed)throw new InvalidArgumentException('Potvrďte stažení produktu z e-shopu.');
                shopCatalogPublicationDeactivate($pdo,$selectedId,$actorId,$reason);
                $_SESSION['product_admin_flash']='Produkt byl stažen z e-shopu. V katalogu zůstal pro další úpravy.';
            }elseif($action!=='create')throw new InvalidArgumentException('Neznámá akce katalogu.');
            header('Location: eshop_produkt_admin.php?id='.$selectedId,true,303);exit;
        }catch(Throwable $exception){$errors[]=$exception->getMessage();}
    }
}
$success=(string)($_SESSION['product_admin_flash']??'');unset($_SESSION['product_admin_flash']);
$allProducts=shopManualCatalogProducts($pdo);$products=$allProducts;$search=trim((string)($_GET['q']??''));$showArchive=($_GET['archiv']??'')==='1';
if($search!=='')$products=array_values(array_filter($products,static fn(array $row):bool=>str_contains(mb_strtolower((string)$row['name'],'UTF-8'),mb_strtolower($search,'UTF-8'))||str_contains(mb_strtolower((string)$row['offer_type'],'UTF-8'),mb_strtolower($search,'UTF-8'))));
elseif(!$showArchive)$products=array_values(array_filter($products,static fn(array$row):bool=>(string)$row['origin']==='manual'||(string)$row['catalog_status']==='active'));
$hiddenArchiveCount=count($allProducts)-count(array_filter($allProducts,static fn(array$row):bool=>(string)$row['origin']==='manual'||(string)$row['catalog_status']==='active'));
$listContext=$showArchive?'&archiv=1':($search!==''?'&q='.rawurlencode($search):'');
$detail=null;$publicationReadiness=null;if($selectedId>0){try{$detail=shopManualCatalogDetail($pdo,$selectedId);$publicationReadiness=shopCatalogPublicationReadiness($pdo,$selectedId);}catch(Throwable $exception){$errors[]=$exception->getMessage();}}
$prefix=shopCatalogManualSkuPrefix();
?>
<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Katalog e-shopu</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"></head><body class="bg-light"><?php include __DIR__.'/hlavicka.php';?>
<script>
document.addEventListener('DOMContentLoaded',()=>{
const definitions=<?=json_encode($attributeDefinitions,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR)?>;
let editorCounter=0;
const addRow=(editor,key='',value='')=>{editor.querySelector('[data-no-attributes]')?.remove();const row=document.createElement('div');row.className='row g-2 align-items-center';row.dataset.attributeRow='';const keyCell=document.createElement('div');keyCell.className='col-md-5';const keyInput=document.createElement('input');keyInput.className='form-control form-control-sm';keyInput.name='attribute_keys[]';keyInput.setAttribute('list',editor.dataset.listId);keyInput.placeholder='Název parametru';keyInput.value=key;keyCell.append(keyInput);const valueCell=document.createElement('div');valueCell.className='col-md-6';valueCell.dataset.valueCell='';const actionCell=document.createElement('div');actionCell.className='col-md-1 d-grid';const remove=document.createElement('button');remove.type='button';remove.className='btn btn-sm btn-outline-danger';remove.dataset.removeAttribute='';remove.setAttribute('aria-label','Odebrat parametr');remove.textContent='×';actionCell.append(remove);row.append(keyCell,valueCell,actionCell);editor.querySelector('[data-attribute-rows]').append(row);
const adapt=()=>{const definition=definitions[keyInput.value]||null;const current=valueCell.querySelector('[data-attribute-value]');const currentValue=current?current.value:value;if(definition&&Number(definition.active)===1&&definition.value_type==='choice'){const select=document.createElement('select');select.className='form-select form-select-sm';select.name='attribute_values[]';select.dataset.attributeValue='';const blank=document.createElement('option');blank.value='';blank.textContent='Vyberte';select.append(blank);const choices=definition.choices||[];if(currentValue!==''&&!choices.includes(currentValue)){const legacy=document.createElement('option');legacy.value=currentValue;legacy.textContent=currentValue+' (stávající hodnota)';legacy.selected=true;select.append(legacy);}for(const choice of choices){const option=document.createElement('option');option.value=choice;option.textContent=choice;option.selected=choice===currentValue;select.append(option);}valueCell.replaceChildren(select);}else{const input=document.createElement('input');input.className='form-control form-control-sm';input.name='attribute_values[]';input.dataset.attributeValue='';input.placeholder=definition&&definition.value_type==='number'?'Číselná hodnota':'Hodnota';input.value=currentValue;valueCell.replaceChildren(input);}};
keyInput.addEventListener('change',adapt);remove.addEventListener('click',()=>{row.remove();if(!editor.querySelector('[data-attribute-row]')){const empty=document.createElement('div');empty.className='small text-muted';empty.dataset.noAttributes='';empty.textContent='Žádné parametry. Produkt lze založit i bez nich.';editor.querySelector('[data-attribute-rows]').append(empty);}});adapt();};
for(const editor of document.querySelectorAll('[data-attribute-editor]')){if(!editor.dataset.listId){editor.dataset.listId=editor.querySelector('datalist')?.id||('attribute-runtime-'+(++editorCounter));for(const row of [...editor.querySelectorAll('[data-attribute-row]')]){const key=row.querySelector('input[name="attribute_keys[]"]')?.value||'';const value=row.querySelector('[data-attribute-value]')?.value||'';row.remove();addRow(editor,key,value);}}editor.querySelector('[data-add-attribute]')?.addEventListener('click',()=>addRow(editor));}
const advanced=[];for(const field of document.querySelectorAll('select[name="offer_type"],select[name="item_type"],input[name="visibility"],select[name="includes_vat"],input[name="vat_rate_basis_points"],input[name="unit_code"],input[name="ean"],[data-attribute-editor]')){const block=field.matches('[data-attribute-editor]')?field:field.closest('[class*="col-"]');if(block&&!advanced.includes(block)){block.classList.add('d-none');advanced.push(block);}}
if(advanced.length){const button=document.createElement('button');button.type='button';button.className='btn btn-sm btn-outline-secondary mb-3';button.textContent='Zobrazit technické údaje';button.dataset.catalogAdvancedToggle='';button.addEventListener('click',()=>{const hidden=advanced.some(block=>block.classList.contains('d-none'));for(const block of advanced)block.classList.toggle('d-none',!hidden);button.textContent=hidden?'Skrýt technické údaje':'Zobrazit technické údaje';});document.querySelector('main > .alert-info')?.insertAdjacentElement('afterend',button);}
});
</script>
<main class="container-fluid py-4" style="max-width:1600px"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3"><div><h1 class="h4 mb-0"><i class="bi bi-box-seam me-2 text-primary"></i>Katalog</h1><div class="small text-muted">Založení, úprava a zveřejnění produktu na jednom místě.</div></div><details class="text-end"><summary class="btn btn-outline-secondary btn-sm">Pokročilé nástroje</summary><div class="card card-body position-absolute end-0 mt-2 shadow-sm" style="z-index:10;min-width:250px"><a class="btn btn-sm btn-link text-start" href="eshop_categories_admin.php">Kategorie</a><a class="btn btn-sm btn-link text-start" href="eshop_attributes_admin.php">Číselník parametrů</a><a class="btn btn-sm btn-link text-start" href="eshop_catalog_admin.php">Hromadná správa</a><a class="btn btn-sm btn-link text-start" href="eshop_admin.php">Jednorázový import Shoptet</a></div></details></div>
