check-input" type="checkbox" name="confirm_action" value="1" id="publishConfirm" required><label class="form-check-label" for="publishConfirm">Zkontroloval/a jsem název, cenu a popis</label></div><div class="col-md-3 d-grid ms-auto"><button class="btn btn-success">Zveřejnit v e-shopu</button></div></form><?php else:?><div class="alert alert-warning mb-0"><strong>Ještě nelze zveřejnit.</strong><ul class="mb-0 mt-2"><?php foreach(($publicationReadiness['blockers']??[])as$blocker):?><li><?=productAdminH($blocker)?></li><?php endforeach;?></ul></div><?php endif;?></div></section>
